        if ($product->getType() == Product::PTYPE_VIRTUAL) {
            $outOfStock = OutOfStockType::OUT_OF_STOCK_AVAILABLE;
        } else {
            $outOfStock = StockAvailable::outOfStock((int) $this->id_product);
